labels={'control':'Контроль','news_only':'Только новости','peers_only':'Только общение','combined':'Новости + общение',
    'combined_memory4':'Память 4 раунда','combined_complete':'Полная сеть','combined_segregated':'Две группы','negative_news':'Обратная новость'}
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False})

fig,axes=plt.subplots(1,2,figsize=(10,3.4))
for condition,color in [('control','#8794a3'),('news_only','#bd8130'),('peers_only','#6480ad'),('combined','#087e8b')]:
    selected=[r for r in runs if r['config']['name']==condition]
    for ax,metric in zip(axes,['mean_opinion','variance']):
        values=[[r['trajectory'][t][metric] for r in selected] for t in range(5)]
        means=[statistics.mean(v) for v in values]
        sds=[statistics.stdev(v) for v in values]
        ax.plot(range(5),means,label=labels[condition],color=color,marker='o',markersize=3)
        ax.fill_between(range(5),[m-s for m,s in zip(means,sds)],[m+s for m,s in zip(means,sds)],color=color,alpha=.12)
        ax.set_xlabel('Раунд');ax.set_xticks(range(5));ax.grid(alpha=.2)
axes[0].set_title('Среднее предпочтение');axes[1].set_title('Дисперсия предпочтений')
axes[1].legend(fontsize=8)
fig.suptitle('Численный контроль через Concordia; 5 начальных состояний',fontsize=11)
fig.tight_layout();fig.savefig(FIG/'controls.png',dpi=180);plt.close(fig)

fig,axes=plt.subplots(1,2,figsize=(10,3.5))
for c,color in [('combined','#087e8b'),('combined_complete','#bd8130'),('combined_segregated','#925b83')]:
    run=next(r for r in runs if r['config']['name']==c and r['config']['seed']==11)
    axes[0].plot(range(5),[t['variance'] for t in run['trajectory']],marker='o',markersize=3,label=labels[c],color=color)
    axes[1].plot(range(6),run['trajectory'][-1]['opinions'],marker='o',label=labels[c],color=color)
axes[0].set(xlabel='Раунд',ylabel='Дисперсия',xticks=list(range(5)))
axes[1].set(xlabel='Номер агента',ylabel='Итоговое предпочтение',xticks=list(range(6)),ylim=(-1,1))
axes[1].axhline(0,color='#b0b0b0',lw=.7);axes[0].legend(fontsize=8)
for ax in axes:ax.grid(alpha=.2)
fig.suptitle('Влияние топологии в численном контроле; пример seed=11',fontsize=11)
fig.tight_layout();fig.savefig(FIG/'topology.png',dpi=180);plt.close(fig)

fig,ax=plt.subplots(figsize=(9,3.3))
for h,color in [(1,'#087e8b'),(20,'#925b83')]:
    r=json.loads((ROOT/f'artifacts/runs/growth_memory{h}.json').read_text(encoding='utf-8'))
    ys=[statistics.mean(len(c['prompt']) for c in r['calls'] if c['round']==t) for t in range(1,21)]
    ax.plot(range(1,21),ys,label=f'Окно памяти: {h}',color=color,marker='o',markersize=3)
ax.set(xlabel='Раунд',ylabel='Символов в промпте',title='Рост входного контекста: измерены символы, не токены')
ax.legend();ax.grid(alpha=.2);fig.tight_layout();fig.savefig(FIG/'memory_growth.png',dpi=180);plt.close(fig)

pages=[]
def page(title,subtitle=''):
    part=[('h1',title)]
    if subtitle:part.append(('lead',subtitle))
    pages.append(part);return part
def p(part,text):part.append(('p',text))
def h(part,text):part.append(('h2',text))
def table(part,headers,rows,widths=None):part.append(('table',(headers,rows,widths)))
def code(part,text):part.append(('code',text))
def img(part,name):part.append(('image',name))

