manifest={}
for folder in ('src','tests','scripts','artifacts'):
    for f in sorted((ROOT/folder).rglob('*')):
        if f.is_file() and '__pycache__' not in f.parts and 'matplotlib-cache' not in f.parts and f.name!='manifest.json':
            manifest[str(f.relative_to(ROOT)).replace('\\','/')]=hashlib.sha256(f.read_bytes()).hexdigest()
for filename in ('requirements.txt','.env.example','README.txt'):
    manifest[filename]=hashlib.sha256((ROOT/filename).read_bytes()).hexdigest()
(ROOT/'artifacts/manifest.json').write_text(json.dumps({'created_utc':datetime.now(timezone.utc).isoformat(),'sha256':manifest},ensure_ascii=False,indent=2),encoding='utf-8')
